runtimeProof.collectorSource:
def snc_runtime_command(label,args,environment,cwd):
    started=time.monotonic()
    try:
        result=subprocess.run(args,cwd=cwd,env=environment,text=True,capture_output=True,timeout=120)
        record={'label':label,'argv':args,'cwd':str(cwd),'environment':environment,'exit':result.returncode,'stdout':result.stdout,'stderr':result.stderr,'durationSeconds':round(time.monotonic()-started,3)}
    except subprocess.TimeoutExpired as error:
        record={'label':label,'argv':args,'cwd':str(cwd),'environment':environment,'exit':None,'failure':'TimeoutExpired','timeoutSeconds':120,'stdout':error.stdout.decode('utf-8',errors='replace') if isinstance(error.stdout,bytes) else (error.stdout or ''),'stderr':error.stderr.decode('utf-8',errors='replace') if isinstance(error.stderr,bytes) else (error.stderr or '')}
        result=None
    streams={}
    for stream in ['stdout','stderr']:
        content=record[stream].encode('utf-8')
        path=snc_runtime_receipt_dir/f'runtime-{len(snc_evidence["validation"]["results"])+1:02d}.{stream}.log'
        path.write_bytes(content)
        streams[stream]={'path':str(path),'bytes':len(content),'sha256':hashlib.sha256(content).hexdigest()}
    record['rawReceipts']=streams
    snc_evidence['validation']['results'].append(record)
    if record['exit']!=0:
        snc_evidence['validation']['failures'].append(record)
        snc_evidence['validation']['state']='STOP: runtime failure; no source edit or completed-PASS rerun authorized'
    write(str(repo/'docs/c1-stable-node-contracts-evidence.json'),json.dumps(snc_evidence,indent=2)+'\n')
    display(record)
    if record['exit']!=0:
        raise RuntimeError('Actual runtime command failed; stop and report without retry')
    return result

