with tempfile.TemporaryDirectory(prefix='c1-stable-node-contracts-runtime-') as temporary:
    root=Path(temporary)
    for name in ['home','tmp']:
        (root/name).mkdir()
    environment={'PATH':'/usr/bin:/bin','HOME':str(root/'home'),'TMPDIR':str(root/'tmp'),'LANG':'C.UTF-8'}
    args=['npm','test','--','test/runtime-resources.test.ts','test/git-diff.test.ts','test/file-mention.test.ts','test/recovery-runner.test.ts','test/session-foundation.test.ts']
    try:
        snc_first_result=snc_runtime_command('Exact first selector form: authored TypeScript paths via npm',args,environment,repo)
    except RuntimeError:
        snc_runtime_stopped=True
    actual=snc_evidence['validation']['results'][-1]
    counts={title:len(re.findall(r'^✔ '+re.escape(title)+r' \(',actual['stdout'],re.MULTILINE)) for title in snc_all_titles}
