snc_supported_stopped=False
with tempfile.TemporaryDirectory(prefix='c1-stable-node-contracts-js-runtime-') as temporary:
    root=Path(temporary)
    for name in ['home','tmp']:
        (root/name).mkdir()
    environment={'PATH':'/usr/bin:/bin','HOME':str(root/'home'),'TMPDIR':str(root/'tmp'),'LANG':'C.UTF-8'}
    commands=[
      ('Corrected first form: bare generated JS via npm',['npm','test','--','test/runtime-resources.test.js','test/git-diff.test.js','test/file-mention.test.js','test/recovery-runner.test.js','test/session-foundation.test.js']),
      ('Original second form: dotted generated JS via npm',['npm','test','--','./test/runtime-resources.test.js','./test/git-diff.test.js','./test/file-mention.test.js','./test/recovery-runner.test.js','./test/session-foundation.test.js']),
      ('Original third form: direct generated JS via Node',['node','--test','test/runtime-resources.test.js','test/git-diff.test.js','test/file-mention.test.js','test/recovery-runner.test.js','test/session-foundation.test.js'])
    ]
    for label,args in commands:
        try:
            result=snc_runtime_command(label,args,environment,repo)
        except RuntimeError:
            snc_supported_stopped=True
            break
        counts={title:len(re.findall(r'^✔ '+re.escape(title)+r' \(',result.stdout,re.MULTILINE)) for title in snc_all_titles}
        summaryOk=all(value in result.stdout for value in ['ℹ tests 55','ℹ pass 55','ℹ fail 0','ℹ cancelled 0','ℹ skipped 0'])
        observation={'label':label,'eachOriginalCaseCount':counts,'all55ExactlyOnce':len(counts)==55 and all(n==1 for n in counts.values()),'zeroFailSkipCancel':summaryOk,'homeEntriesAfterCommand':sorted(p.name for p in (root/'home').iterdir()),'tmpEntriesAfterCommand':sorted(p.name for p in (root/'tmp').iterdir())}
        snc_evidence['runtimeProof']['supportedForms']['observations'].append(observation)
        if not observation['all55ExactlyOnce'] or not summaryOk:
            snc_supported_stopped=True
            snc_evidence['validation']['failures'].append({'kind':'Required case-count/summary condition failed','observation':observation})
            break
    snc_supported_runtime_root=str(root)
try:
    Path(snc_supported_runtime_root).lstat()
    raise AssertionError('Owned supported-runtime root still exists')
except FileNotFoundError:
    snc_evidence['runtimeProof']['supportedForms']['cleanup']={'path':snc_supported_runtime_root,'observation':'lstat ENOENT after owned TemporaryDirectory cleanup'}
